33175.a:
```hcl
terraform {
  required_providers { aws = { source = "hashicorp/aws", version = "~> 5.0" } }
}
provider "aws" { region = var.region }

variable "region" { type = string  default = "eu-central-1" }

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"]
  filter { name = "name" values = ["ubuntu/images/*24.04-amd64-server-*"] }
}

resource "aws_instance" "web" {
  ami           = data.aws_ami.ubuntu.id
  instance_type = "t3.micro"
  tags = { Name = "web" }
}

output "public_ip" { value = aws_instance.web.public_ip }
```
Reference `aws_instance.web.id` — Terraform shundan dependency graph quradi.

33186.a:
```hcl
resource "aws_db_instance" "main" {
  lifecycle { prevent_destroy = true }
  deletion_protection = true          # cloud darajasida ham
}

resource "aws_launch_template" "lt" {
  lifecycle { create_before_destroy = true }
}

resource "aws_ecs_service" "api" {
  lifecycle { ignore_changes = [desired_count] }  # autoscaler boshqaradi
}
```
Gotcha: `create_before_destroy` unique nomli resurslarda (bir xil nom) to'qnashadi — `name_prefix` ishlating.
`prevent_destroy` faqat Terraform ichida; kodni o'chirsangiz himoya ham ketadi — cloud-side deletion protection ham yoqing.

33214.a:
```nginx
server {
    listen 80;
    server_name api.example.com;

    location / {
        proxy_pass http://127.0.0.1:8080;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
```
Header'larsiz backend hamma so'rovni `127.0.0.1`dan kelgan deb ko'radi va redirect'larda noto'g'ri host/sxema beradi.
Ilova `X-Forwarded-For`ga faqat ishonchli proxy'dan kelganda ishonishi kerak (spoofing).

33218.a:
```nginx
server {
    listen 80;
    server_name example.com;
    return 301 https://$host$request_uri;
}
server {
    listen 443 ssl;
    http2 on;
    server_name example.com;
    ssl_certificate     /etc/letsencrypt/live/example.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/example.com/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_cache shared:SSL:10m;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
}
```
- `fullchain.pem` (intermediate bilan) — faqat `cert.pem` bo'lsa ba'zi client'lar "unable to verify" beradi.
- HSTS'ni yoqishdan oldin hamma subdomain HTTPS'da ekaniga ishonch hosil qiling (qaytarib olish qiyin).
- Tekshirish: `testssl.sh`, SSL Labs.

33219.a:
```nginx
upstream api {
    least_conn;
    server 10.0.1.10:8080 max_fails=3 fail_timeout=10s;
    server 10.0.1.11:8080 max_fails=3 fail_timeout=10s;
    server 10.0.1.12:8080 backup;
    keepalive 32;                 # backend'ga ulanishlarni qayta ishlatish
}
server {
    location / {
        proxy_pass http://api;
        proxy_http_version 1.1;
        proxy_set_header Connection "";   # keepalive uchun shart
        proxy_next_upstream error timeout http_502;
    }
}
```
`proxy_next_upstream` POST'ni boshqa server'ga qayta yuborishi mumkin — non-idempotent so'rovlarda ehtiyot (default'da non-idempotent qayta yuborilmaydi).

33221.a:
```nginx
http {
    limit_req_zone $binary_remote_addr zone=api:10m rate=10r/s;
    limit_conn_zone $binary_remote_addr zone=conn:10m;
    server_tokens off;
    client_max_body_size 10m;

    server {
        location /api/login {
            limit_req zone=api burst=20 nodelay;
            limit_req_status 429;
            limit_conn conn 10;
            proxy_pass http://api;
        }
    }
}
```
Gotcha: Nginx LB/CDN ortida bo'lsa `$remote_addr` = LB IP, hamma bitta limitga tushadi — `real_ip_header X-Forwarded-For` + `set_real_ip_from <LB CIDR>`.

33222.a:
```nginx
worker_processes auto;
worker_rlimit_nofile 65535;
events { worker_connections 8192; }
http {
    sendfile on; tcp_nopush on;
    keepalive_timeout 30s;
    gzip on; gzip_types application/json text/css application/javascript;
    proxy_cache_path /var/cache/nginx keys_zone=c:50m max_size=1g inactive=10m;
    server {
        location /api/catalog {
            proxy_cache c;
            proxy_cache_valid 200 1m;
            proxy_cache_use_stale error timeout updating;   # backend yiqilsa eski javob
            proxy_cache_lock on;                            # stampede'dan himoya
            add_header X-Cache $upstream_cache_status;
            proxy_pass http://api;
        }
    }
}
```
O'lchang: `stub_status`/nginx-exporter, `$request_time` vs `$upstream_response_time` — kechikish Nginx'dami yoki backend'da.

33223.a:
```nginx
map $http_upgrade $connection_upgrade { default upgrade; '' close; }

location /ws/ {
    proxy_pass http://ws_backend;
    proxy_http_version 1.1;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection $connection_upgrade;
    proxy_read_timeout 1h;        # default 60s — jim ulanish uziladi
}

server {
    listen 443 ssl;
    http2 on;
    location /payments.v1.PaymentService/ { grpc_pass grpc://10.0.1.20:9090; }
}
```
Reload'da eski worker WebSocket ulanishlari tugaguncha yashaydi — `worker_shutdown_timeout` qo'ying, client reconnect logikasi bo'lsin.
